import java.util.*;
import java.io.*;

public class Main {
    static final int Lg = 18;
    static final int Tw = 1 << Lg;
    static final int Max = Tw + 10;
    static int[][] matrix = new int[Max][Lg + 3];
    static int[] buffer = new int[Lg + 3];
    static int[] buffer2 = new int[Lg + 3];
    static long[] factorial = new long[Max];
    static long[] inv_factorial = new long[Max];
    static List<Integer> positions = new ArrayList<>();
    static int count_bits;
    static int n_value;
    static int mod;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int K = Integer.parseInt(st.nextToken());
        mod = Integer.parseInt(br.readLine());
        int total_pow = power_mod(K, n);
        if ((n & 1) == 1) {
            System.out.println(total_pow);
            return;
        }
        count_bits = Integer.bitCount(n);
        int original_n = n;
        for (int i = 0; i < Lg; i++) {
            if (((n >> i) & 1) == 1) {
                positions.add(i);
            }
        }
        n_value = (1 << count_bits) - 1;
        factorial[0] = 1;
        for (int i = 1; i < Max; i++) {
            factorial[i] = (factorial[i - 1] * i) % mod;
        }
        inv_factorial[Max - 1] = power_mod(factorial[Max - 1], mod - 2);
        for (int i = Max - 2; i >= 0; i--) {
            inv_factorial[i] = (inv_factorial[i + 1] * (i + 1)) % mod;
        }
        for (int i = 0; i <= n_value; i++) {
            int val = 0;
            for (int j = 0; j < count_bits; j++) {
                if (((i >> j) & 1) == 1) {
                    val += (1 << positions.get(j));
                }
            }
            matrix[i][Integer.bitCount(i)] = (int) inv_factorial[val];
        }
        forward_transform(matrix);
        for (int i = 0; i <= n_value; i++) {
            int K_copy = K;
            Arrays.fill(buffer2, 0);
            buffer2[0] = 1;
            while (K_copy > 0) {
                if ((K_copy & 1) == 1) {
                    multiply_convolution(buffer2, buffer2, matrix[i]);
                }
                multiply_convolution(matrix[i], matrix[i], matrix[i]);
                K_copy >>= 1;
            }
            System.arraycopy(buffer2, 0, matrix[i], 0, buffer.length);
        }
        inverse_transform(matrix);
        long result = (total_pow - ((long) matrix[n_value][count_bits] * factorial[original_n]) % mod) % mod;
        if (result < 0) result += mod;
        System.out.println(result);
    }

    static int power_mod(int base, int exponent) {
        long result = 1;
        long b = base;
        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                result = (result * b) % mod;
            }
            b = (b * b) % mod;
            exponent >>= 1;
        }
        return (int) result;
    }

    static void add_arrays(int[] dest, int[] src) {
        for (int i = 0; i <= count_bits; i++) {
            dest[i] = (dest[i] + src[i]) % mod;
        }
    }

    static void subtract_arrays(int[] dest, int[] src) {
        for (int i = 0; i <= count_bits; i++) {
            dest[i] = (dest[i] - src[i]) % mod;
            if (dest[i] < 0) dest[i] += mod;
        }
    }

    static void multiply_convolution(int[] res, int[] a, int[] b) {
        Arrays.fill(buffer, 0);
        for (int i = 0; i <= count_bits; i++) {
            for (int j = 0; j <= i; j++) {
                buffer[i] = (int) ((buffer[i] + (long) a[j] * b[i - j]) % mod);
            }
        }
        System.arraycopy(buffer, 0, res, 0, buffer.length);
    }

    static void forward_transform(int[][] a) {
        for (int i = 0; i < count_bits; i++) {
            for (int msk = n_value; msk >= 0; msk--) {
                if (((msk >> i) & 1) == 1) {
                    add_arrays(a[msk], a[msk ^ (1 << i)]);
                }
            }
        }
    }

    static void inverse_transform(int[][] a) {
        for (int i = 0; i < count_bits; i++) {
            for (int msk = 0; msk >= 0; msk--) {
                if (((msk >> i) & 1) == 1) {
                    subtract_arrays(a[msk], a[msk ^ (1 << i)]);
                }
            }
        }
    }
}
